class ParseError extends Error {}
const fail = (m) => { throw new ParseError(m) }

const newTable = () => ({ t: 'table', m: new Map(), header: false })
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

function parseLine(src, state) {
  let i = 0
  const peek = () => src[i]
  const skipWs = () => { while (i < src.length && isWs(src[i])) i++ }
  const atEnd = () => i >= src.length || src[i] === '#' || src[i] === ';'

  function basicString() {
    i++
    let out = ''
    for (;;) {
      if (i >= src.length) fail('unterminated string')
      const c = src[i]
      if (c === '"') { i++; return out }
      if (c === '\\') {
        i++
        if (i >= src.length) fail('unterminated string')
        const e = src[i]
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.prototype.hasOwnProperty.call(map, e)) { out += map[e]; i++ }
        else if (e === 'u') {
          const h = src.slice(i + 1, i + 5)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          i += 5
        } else fail('invalid escape \\' + String.fromCodePoint(src.codePointAt(i)))
      } else { out += c; i++ }
    }
  }
  function literalString() {
    const j = src.indexOf("'", i + 1)
    if (j < 0) fail('unterminated string')
    const s = src.slice(i + 1, j)
    i = j + 1
    return s
  }
  function name() {
    const c = peek()
    if (c === '"') return basicString()
    if (c === "'") return literalString()
    if (!isBare(c)) fail('expected a name')
    const s = i
    while (isBare(src[i])) i++
    return src.slice(s, i)
  }
  function dotted() {
    const parts = [name()]
    for (;;) {
      const save = i
      skipWs()
      if (peek() === '.') { i++; skipWs(); parts.push(name()) } else { i = save; break }
    }
    return parts
  }

  // Walk intermediate names; returns the table to operate in.
  function walk(table, path, names) {
    const p = path.slice()
    for (const n of names) {
      p.push(n)
      let node = table.m.get(n)
      if (node === undefined) { node = newTable(); table.m.set(n, node) }
      if (node.t === 'array' && node.aot) node = node.items[node.items.length - 1]
      if (node.t !== 'table') fail(`${p.join('.')} is not a table`)
      table = node
    }
    return { table, path: p }
  }

  function assign(table, path, names, value) {
    const w = walk(table, path, names.slice(0, -1))
    const last = names[names.length - 1]
    if (w.table.m.has(last)) fail(`key ${[...w.path, last].join('.')} is defined twice`)
    w.table.m.set(last, value)
  }

  function value(path) {
    skipWs()
    const c = peek()
    if (i >= src.length || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return { t: 'string', v: basicString() }
    if (c === "'") return { t: 'string', v: literalString() }
    if (c === '[') {
      i++
      const arr = { t: 'array', items: [], aot: false }
      for (;;) {
        skipWs()
        if (atEnd()) fail('unterminated array')
        if (peek() === ']') { i++; return arr }
        arr.items.push(value([...path.slice(0, -1), (path.length ? path[path.length - 1] : '') + `[${arr.items.length}]`]))
        skipWs()
        if (peek() === ',') { i++; continue }
        if (peek() === ']') { i++; return arr }
        fail('unterminated array')
      }
    }
    if (c === '{') {
      i++
      const tbl = newTable()
      let first = true
      for (;;) {
        skipWs()
        if (atEnd()) fail('unterminated inline table')
        if (first && peek() === '}') { i++; return tbl }
        first = false
        const names = dotted()
        skipWs()
        if (peek() !== '=') fail('expected = in an inline table')
        i++
        const w = walk(tbl, path, names.slice(0, -1))
        const v = value([...w.path, names[names.length - 1]])
        assign(tbl, path, names, v)
        skipWs()
        if (peek() === ',') { i++; continue }
        if (peek() === '}') { i++; return tbl }
        fail('unterminated inline table')
      }
    }
    const s = i
    while (i < src.length && !isWs(src[i]) && src[i] !== ',' && src[i] !== ']' && src[i] !== '}') i++
    const w = src.slice(s, i)
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    const int = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${int}$`).test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')) }
    if (new RegExp(`^[+-]?${int}(?:\\.${int}(?:[eE][+-]?${int})?|[eE][+-]?${int})$`).test(w)) {
      return { t: 'float', v: Number(w.replace(/_/g, '')) }
    }
    fail(`invalid value ${w}`)
  }

  skipWs()
  if (i >= src.length || src[i] === '#' || src[i] === ';') return

  if (src[i] === '[') {
    const arr = src[i + 1] === '['
    i += arr ? 2 : 1
    skipWs()
    const names = dotted()
    skipWs()
    if (peek() !== ']') fail('unterminated table header')
    i++
    if (arr) {
      if (peek() !== ']') fail('unterminated table header')
      i++
    }
    skipWs()
    if (!atEnd()) fail('trailing text after a table header')
    const w = walk(state.root, [], names.slice(0, -1))
    const last = names[names.length - 1]
    const full = [...w.path, last]
    let node = w.table.m.get(last)
    if (arr) {
      if (node === undefined) { node = { t: 'array', items: [], aot: true }; w.table.m.set(last, node) }
      if (node.t !== 'array' || !node.aot) fail(`${full.join('.')} is not an array of tables`)
      const t = newTable()
      node.items.push(t)
      state.cur = t
    } else {
      if (node === undefined) { node = newTable(); w.table.m.set(last, node) }
      if (node.t !== 'table') fail(`${full.join('.')} is not a table`)
      if (node.header) fail(`table ${full.join('.')} is defined twice`)
      node.header = true
      state.cur = node
    }
    state.path = full
    return
  }

  const names = dotted()
  skipWs()
  if (peek() !== '=') fail('expected key = value')
  i++
  const w = walk(state.cur, state.path, names.slice(0, -1))
  const v = value([...w.path, names[names.length - 1]])
  skipWs()
  if (!atEnd()) fail('trailing text after a value')
  assign(state.cur, state.path, names, v)
}

function cmp(a, b) {
  let i = 0, j = 0
  while (i < a.length && j < b.length) {
    const x = a.codePointAt(i), y = b.codePointAt(j)
    if (x !== y) return x - y
    i += x > 0xffff ? 2 : 1
    j += y > 0xffff ? 2 : 1
  }
  return (a.length - i) - (b.length - j)
}
const sortedKeys = (m) => [...m.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  switch (n.t) {
    case 'string': return JSON.stringify(n.v)
    case 'boolean': return String(n.v)
    case 'integer': return n.v.toString()
    case 'float': return JSON.stringify(n.v)
    case 'array':
      if (!n.items.length) return '[]'
      return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
    default: {
      if (!n.m.size) return '{}'
      return '{\n' + sortedKeys(n.m).map((k) => pad + JSON.stringify(k) + ': ' + toJson(n.m.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
    }
  }
}

function keyLines(n, path, out) {
  if (n.t === 'table') {
    for (const k of sortedKeys(n.m)) {
      const p = path === null ? k : path + '.' + k
      const c = n.m.get(k)
      out.push(`${p} ${c.t}`)
      keyLines(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, idx) => {
      const p = `${path}[${idx}]`
      out.push(`${p} ${c.t}`)
      keyLines(c, p, out)
    })
  }
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  const state = { root, cur: root, path: [] }
  for (let n = 0; n < lines.length; n++) {
    try {
      parseLine(lines[n], state)
    } catch (e) {
      if (!(e instanceof ParseError)) throw e
      process.stderr.write(`error: line ${n + 1}: ${e.message}\n`)
      process.exit(2)
    }
  }
  if (args[0] === 'json') process.stdout.write(toJson(root, 0) + '\n')
  else {
    const out = []
    keyLines(root, null, out)
    process.stdout.write(out.map((l) => l + '\n').join(''))
  }
}

main()
"}

